INSERT INTO crm_contacts (company_id, email, name, first_interaction, last_interaction, hidden, team_id) VALUES ($1, $2, $3, $4, $5, $7, $8) ON CONFLICT (company_id, email) DO UPDATE SET name = COALESCE(crm_contacts.name, EXCLUDED.name), updated_at = now(), first_interaction = CASE WHEN $6 THEN LEAST(crm_contacts.first_interaction, EXCLUDED.first_interaction) ELSE crm_contacts.first_interaction END, last_interaction = GREATEST(crm_contacts.last_interaction, EXCLUDED.last_interaction) RETURNING id
